import{z as o,x as A,o as E,c as d,q as B,j as l,D as e,d as t,s as n,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"代价估计","description":"","frontmatter":{"title":"代价估计","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cost-estimate.md","filePath":"cs/cost-estimate.md","lastUpdated":1791413859000}'),p={name:"cs/cost-estimate.md"};function m(c,a,h,C,f,u){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=B('<h1 id="代价估计" tabindex="-1">代价估计 <a class="header-anchor" href="#代价估计" aria-label="Permalink to &quot;代价估计&quot;">​</a></h1><div class="epigraph"><p>优化器比较的不是感觉，而是页 I/O 与 CPU 的估计；统计错了，再漂亮的搜索也选错树。</p><footer>—— 据 Selinger et al., 1979；Mannino, Chu and Sager 对目录统计的综述整理</footer></div><p><a href="/cs/query-plan">上一课</a>把查询收成物理计划树。本课不重画迭代器。缺口是：候选计划很多，必须给每棵树一个可比较的数。代价估计用目录里的基数、选择率与页数，把「看起来快」换成可加的模型；模型错，计划仍合法，只是慢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>嵌套循环与哈希连接都实现同一 \\(\\bowtie\\)，选谁取决于输入多大、谓词多残、内存够不够。缺口不是新算子，而是<strong>统计加公式</strong>：表的页数 \\(N\\)、元组数 \\(T\\)、索引高度、谓词选择率 \\(f\\)。没有这些，System R 式的搜索只是枚举。</p><p>本课不把直方图的全部种类写完，只锁定：估计是计划节点上的基数与代价，沿树自底向上加。</p><p><span class="marginnote">独立假设：合取谓词的选择率相乘。相关列上它会错，这是估计的边界，不是「优化器坏了」。后课改写仍依赖这些数来决定是否下推、是否用索引。</span></p><p><span class="marginnote">选择率可以翻译成「过滤后剩下几成」：0.1 就是每 10 行留 1 行。数字实例：10 万行的表过 <code>status=&#39;paid&#39;</code>（估 \\(f=0.1\\)）剩 1 万行，再过独立谓词 \\(f=0.5\\) 剩 5 千行——合取就是连乘，两列若强相关，这个乘法就系统性翻车。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>顺序扫描代价大致与页数成正比。索引点查与树高、叶链长度有关。连接：嵌套循环用外层基数乘内层一次查找代价；哈希连接用建表与探针的 I/O；排序用外排趟数。CPU 项（比较、哈希）可加，但外存主导时页项先钉死。</p>',10)),(E(),l(i,null,{default:e(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E7%9B%AE%E5%BD%95%3A%20%E9%A1%B5%E6%95%B0%20%2F%20%E5%9F%BA%E6%95%B0%20%2F%20%E7%9B%B4%E6%96%B9%E5%9B%BE%22%5D%20--%3E%20CARD%5B%22%E5%9F%BA%E6%95%B0%E4%BC%B0%E8%AE%A1%22%5D%0A%20%20CARD%20--%3E%20COST%5B%22%E8%8A%82%E7%82%B9%E4%BB%A3%E4%BB%B7%22%5D%0A%20%20COST%20--%3E%20PICK%5B%22%E5%9C%A8%E8%AE%A1%E5%88%92%E7%A9%BA%E9%97%B4%E4%B8%AD%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A%20%20PICK%20--%3E%20RW%5B%22%E5%90%8E%E8%AF%BE%3A%20%E6%9F%A5%E8%AF%A2%E6%94%B9%E5%86%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"估计沿计划传播：选择改变基数，投影几乎不改（集合下去重才改），连接输出基数用选择率乘两输入。优化器拿总和（或加权 I/O+CPU）给动态规划或启发式搜索当目标函数。缓冲区大小进入公式：嵌套循环是否击中缓冲，改变有效 I/O。",-1)),(E(),l(i,null,{default:e(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%A1%A8%20T%20%E5%85%B1%20100000%20%E8%A1%8C%22%5D%20--%3E%20B%5B%22%E9%80%89%E6%8B%A9%E4%BC%B0%E8%AE%A1%E8%BE%93%E5%87%BA%2010000%20%E8%A1%8C%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%BF%9E%E6%8E%A5%E4%BC%B0%E8%AE%A1%E8%BE%93%E5%87%BA%2010000%20%E4%B9%98%E5%AF%B9%E7%AB%AF%E9%80%89%E6%8B%A9%E7%8E%87%22%5D%0A%20%20C%20--%3E%20D%5B%22%E8%8A%82%E7%82%B9%E4%BB%A3%E4%BB%B7%20I%2FO%20%E4%B8%8E%20CPU%20%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%85%A8%E6%A0%91%E6%80%BB%E4%BB%A3%E4%BB%B7%E4%BA%A4%E7%BB%99%E6%90%9C%E7%B4%A2%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">这张图回答「一个估计从叶子到根怎么走」：每个算子拿输入基数套自己的公式算输出基数，再算本节点代价，自底向上累加。乘错一层，上面的连接策略、排序选择全跟着偏——这就是过期统计危害的来源。</span></p><p>过期统计使估计偏离真实基数，计划仍可运行——<a href="/cs/wal">WAL</a>与正确性无关，只是选错了树。本课把「正确」与「最优」分开：正确由代数指称管，最优由这套数管。</p><p><span class="marginnote">直觉类比：代价模型像装修报价单，不保证最终花费分毫不差，但能把「全屋重铺」和「只刷一面墙」放进同一张单子比较。统计过期就像按三年前的材料价报价——房子照样能装完，只是方案可能不划算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证最优。搜索空间被剪枝（左深树），代价模型是近似，参数会过期。也不把机器学习代价模型请进主干。分布式、缓存感知的精细模型是实现细节。</p><p>直方图与最频值能放松独立假设的一部分，仍是估计，不是计数。后课默认：谈到选计划，先有基数与代价；改写改变的是逻辑树，再重新估计。</p><p>优化器是在估计下的搜索，不是证明最快。统计刷新是运维，不是本课的公式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>计划已在；本课只给树上可加的 I/O/CPU 估计。</li><li>统计与独立假设会错，选错树不等于查错结果。</li><li>逻辑改写后课才动树的形状。</li><li>出处：Selinger et al., 1979；Ramakrishnan and Gehrke；Garcia-Molina, Ullman and Widom。</li></ul>',9))])}const T=o(p,[["render",m]]);export{D as __pageData,T as default};
